{
  "name": "IMS电机轴",
  "name_en": "IMS motor axis",
  "manufacturer": "",
  "description": "一种用于实验室和光束线装置中的电动运动轴，通常驱动直线或旋转定位机构，对样品、光学元件或诊断部件进行精密位置调整。该类电机支持回零、限位管理、状态监测和故障清除，适合需要可靠重复定位的实验场景。",
  "description_en": "A motorized motion axis used in laboratory and beamline systems to drive linear or rotary positioning mechanisms for precise adjustment of samples, optics, or diagnostics. This type of motor supports homing, limit management, status monitoring, and fault clearing, making it suitable for experiments that require reliable repeatable positioning.",
  "tag_hints": [
    "motorized positioning",
    "beamline motion control",
    "sample and optics alignment",
    "homing",
    "soft limits",
    "fault flag clearing",
    "precision motion axis"
  ],
  "actions": [
    {
      "action_name": "auto-move",
      "description": "移动电机到目标位置",
      "description_en": "Move the motor to a target position"
    },
    {
      "action_name": "auto-format_status_info",
      "description": "格式化设备状态信息",
      "description_en": "Format device status information"
    },
    {
      "action_name": "auto-limits",
      "description": "获取运动软限位范围",
      "description_en": "Get the motion soft limit range"
    },
    {
      "action_name": "auto-msta",
      "description": "获取电机状态位字段",
      "description_en": "Get the motor status bit fields"
    },
    {
      "action_name": "auto-homed",
      "description": "获取电机是否已回零",
      "description_en": "Get whether the motor is homed"
    },
    {
      "action_name": "auto-enable",
      "description": "设置电机启用状态",
      "description_en": "Set the motor enabled state"
    },
    {
      "action_name": "auto-disable",
      "description": "设置电机禁用状态",
      "description_en": "Set the motor disabled state"
    },
    {
      "action_name": "auto-check_value",
      "description": "检查目标位置是否有效",
      "description_en": "Check whether the target position is valid"
    },
    {
      "action_name": "auto-check_limit_switches",
      "description": "检查限位开关状态",
      "description_en": "Check the limit switch status"
    },
    {
      "action_name": "auto-get_low_limit",
      "description": "获取低软限位",
      "description_en": "Get the low soft limit"
    },
    {
      "action_name": "auto-set_low_limit",
      "description": "设置低软限位",
      "description_en": "Set the low soft limit"
    },
    {
      "action_name": "auto-get_high_limit",
      "description": "获取高软限位",
      "description_en": "Get the high soft limit"
    },
    {
      "action_name": "auto-set_high_limit",
      "description": "设置高软限位",
      "description_en": "Set the high soft limit"
    },
    {
      "action_name": "auto-clear_limits",
      "description": "清除已配置的软限位",
      "description_en": "Clear the configured soft limits"
    },
    {
      "action_name": "auto-set_current_position",
      "description": "设置当前位置参考值",
      "description_en": "Set the current position reference"
    },
    {
      "action_name": "auto-egu",
      "description": "获取工程单位",
      "description_en": "Get the engineering units"
    },
    {
      "action_name": "auto-filter",
      "description": "过滤设备相关日志或状态消息",
      "description_en": "Filter device-related log or status messages"
    },
    {
      "action_name": "auto-spg_stop",
      "description": "停止电机运动",
      "description_en": "Stop motor motion"
    },
    {
      "action_name": "auto-spg_pause",
      "description": "暂停电机运动",
      "description_en": "Pause motor motion"
    },
    {
      "action_name": "auto-spg_go",
      "description": "恢复或允许电机运动",
      "description_en": "Resume or allow motor motion"
    },
    {
      "action_name": "auto-screen",
      "description": "打开设备控制界面",
      "description_en": "Open the device control screen"
    },
    {
      "action_name": "auto-stage",
      "description": "准备电机投入使用并清除初始化标志",
      "description_en": "Prepare the motor for use and clear initialization flags"
    },
    {
      "action_name": "auto-auto_setup",
      "description": "自动完成电机初始化并清除常见故障标志",
      "description_en": "Automatically initialize the motor and clear common fault flags"
    },
    {
      "action_name": "auto-reinitialize",
      "description": "重新初始化电机",
      "description_en": "Reinitialize the motor"
    },
    {
      "action_name": "auto-clear_all_flags",
      "description": "清除全部电机标志",
      "description_en": "Clear all motor flags"
    },
    {
      "action_name": "auto-clear_powerup",
      "description": "清除上电标志",
      "description_en": "Clear the power-up flag"
    },
    {
      "action_name": "auto-clear_stall",
      "description": "清除堵转标志",
      "description_en": "Clear the stall flag"
    },
    {
      "action_name": "auto-clear_error",
      "description": "清除错误标志",
      "description_en": "Clear the error flag"
    },
    {
      "action_name": "auto-md",
      "description": "获取或设置设备元数据",
      "description_en": "Get or set device metadata"
    },
    {
      "action_name": "auto-configure",
      "description": "应用电机配置参数",
      "description_en": "Apply a motor configuration"
    },
    {
      "action_name": "auto-get_configuration",
      "description": "获取当前配置名称",
      "description_en": "Get the current configuration name"
    },
    {
      "action_name": "auto-get_configuration_values",
      "description": "获取配置参数值",
      "description_en": "Get configuration parameter values"
    },
    {
      "action_name": "auto-get_current_values",
      "description": "获取当前参数值",
      "description_en": "Get the current parameter values"
    },
    {
      "action_name": "auto-find_configuration",
      "description": "查找匹配的配置",
      "description_en": "Find matching configurations"
    },
    {
      "action_name": "auto-diff_configuration",
      "description": "比较当前设置与配置之间的差异",
      "description_en": "Compare the current settings with a configuration"
    },
    {
      "action_name": "auto-setup_pmgr",
      "description": "设置参数管理连接",
      "description_en": "Set up the parameter manager connection"
    },
    {
      "action_name": "auto-check_pmgr",
      "description": "检查参数管理状态",
      "description_en": "Check the parameter manager status"
    },
    {
      "action_name": "auto-home",
      "description": "执行回零",
      "description_en": "Home the motor"
    },
    {
      "action_name": "auto-subscribe",
      "description": "订阅设备位置或状态更新",
      "description_en": "Subscribe to device position or status updates"
    },
    {
      "action_name": "auto-done_comparator",
      "description": "判断运动完成条件是否满足",
      "description_en": "Evaluate whether the motion-complete condition is met"
    }
  ]
}

